    providerKind: provider,
    modelId: effectiveModelId,
    baseUrl: keepSavedPair ? baseUrl : (parsed.baseUrl ?? degradedDefault),
    provenance: BindingProvenance.flag,
  );
}","path":"lib/src/cli/startup.dart"}

