String? _familyExclusiveEndpointDialect(String baseUrl) {
  String? verdict;
  for (final (name, dialect) in const [
    ('anthropic', anthropicMessagesApi),
    ('openai', 'openai-completions'),
    ('google', 'google-generative-ai'),
  ]) {
